-- Migration: BiblePlace Geocoding Table and Data
-- Sourced from OpenBible.info Bible Geocoding Data (CC-BY 4.0)

CREATE TABLE IF NOT EXISTS public."BiblePlace" (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    lat DOUBLE PRECISION NOT NULL,
    lng DOUBLE PRECISION NOT NULL,
    confidence INTEGER DEFAULT 500,
    verse_refs TEXT[] DEFAULT '{}',
    verse_count INTEGER NOT NULL DEFAULT 0,
    image_url TEXT,
    image_attribution TEXT,
    image_credit_url TEXT,
    is_featured BOOLEAN NOT NULL DEFAULT FALSE,
    featured_note TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes for fast geo & name search
CREATE INDEX IF NOT EXISTS idx_bible_places_name ON public."BiblePlace" (name);
CREATE INDEX IF NOT EXISTS idx_bible_places_featured ON public."BiblePlace" (is_featured);

-- RLS: Public read-only access
ALTER TABLE public."BiblePlace" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public read of BiblePlace" ON public."BiblePlace" FOR SELECT USING (true);

-- Seed Data
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  lat = EXCLUDED.lat,
  lng = EXCLUDED.lng,
  confidence = EXCLUDED.confidence,
  verse_refs = EXCLUDED.verse_refs,
  verse_count = EXCLUDED.verse_count,
  image_url = EXCLUDED.image_url,
  image_attribution = EXCLUDED.image_attribution,
  is_featured = EXCLUDED.is_featured,
  featured_note = EXCLUDED.featured_note;
